const FALLBACK_ART='assets/relic/token-emblem-v2.png';
const COPY=[['THE FORGOTTEN TEMPLE','Moderate','A sunken sanctuary surrounding the first known signal.'],['THE ABYSSAL ARCHIVE','Severe','A drowned repository beneath a lightless planetary sea.'],['THE ASHEN CITY','High','A glass-black metropolis preserved beneath metallic ash.'],['THE CELESTIAL RUINS','Extreme','Orbital monuments adrift above a fractured world.'],['THE OBSIDIAN VAULT','Unknown','A sealed chamber older than every recovered record.']];
const state={account:null,authenticated:false,regions:[],relics:[],civilizations:[],selectedRegion:null,selectedRelic:null,rarity:'',search:'',sort:'latest'};
const API=(window.RELIC_ZERO_API_BASE||'').replace(/\/$/,'');
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const safe=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const short=a=>a?`${a.slice(0,6)}…${a.slice(-4)}`:'CONNECT WALLET';
const date=v=>v?new Intl.DateTimeFormat('en',{dateStyle:'medium'}).format(new Date(v)):'—';
const art=r=>r?.imageUrl||r?.imageURL||r?.image||FALLBACK_ART;
function toast(m){const n=$('#toast');n.textContent=m;n.classList.add('show');clearTimeout(n.timer);n.timer=setTimeout(()=>n.classList.remove('show'),3200)}
async function api(path,o={}){if(!API)throw Error('BACKEND_UNAVAILABLE');const r=await fetch(`${API}${path}`,{credentials:'include',headers:{'content-type':'application/json',...(o.headers||{})},...o}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||`HTTP_${r.status}`);return d}
function message(e){if(e.message==='BACKEND_UNAVAILABLE')return'Production data service is not configured.';if(['UNAUTHORIZED','HTTP_401'].includes(e.message))return'Authenticate your wallet to access private records.';return`Data unavailable (${e.message}).`}
function route(){const id=(location.hash||'#home').slice(1),target=document.getElementById(id)||$('#home');$$('.view').forEach(v=>v.classList.toggle('active',v===target));$$('.links a').forEach(a=>a.classList.toggle('active',a.hash===`#${target.id}`));$('.links').classList.remove('open');$('#walletMenu').classList.remove('show');scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});if(id==='leaderboard')loadLeaderboard();if(id==='profile')loadProfile();if(id==='relics'&&state.authenticated)loadRelics()}
function renderRegions(){const rows=state.regions.length?state.regions:COPY.map((c,i)=>({id:'',name:c[0],difficulty:c[1],description:c[2],unavailable:true,index:i}));$('#regionGrid').innerHTML=rows.slice(0,5).map((r,i)=>`<article class="region ${r.unavailable?'locked':''}" data-index="${i}"><label>REGION 0${i+1}</label><h3>${safe(r.name||COPY[i]?.[0])}</h3><p>${safe(r.description||COPY[i]?.[2]||'Verified region record.')}</p><small>DIFFICULTY · ${safe(r.difficulty||COPY[i]?.[1]||'UNSPECIFIED')}<br>ELIGIBILITY · ${r.id?'SERVER VERIFIED AT LAUNCH':'SERVICE REQUIRED'}</small></article>`).join('');$$('.region').forEach(c=>c.onclick=()=>{const r=rows[+c.dataset.index];if(!r?.id)return toast('This visual region has no matching production record yet.');state.selectedRegion=r;$$('.region').forEach(x=>x.classList.toggle('selected',x===c));$('#expeditionTitle').textContent=r.name;$('#expeditionStatus').textContent=state.account?'Eligibility will be verified by the server at launch.':'Connect a wallet to continue.';$('#expeditionBtn').disabled=!state.account})}
function renderRelics(){const q=state.search.toLowerCase();let rows=state.relics.filter(r=>(!state.rarity||r.rarity===state.rarity)&&(!q||`${r.name} ${r.civilization?.name||''}`.toLowerCase().includes(q)));rows.sort((a,b)=>(state.sort==='oldest'?1:-1)*(new Date(a.createdAt)-new Date(b.createdAt)));$('#relicGrid').innerHTML=rows.map(r=>`<article class="relic-card" data-id="${safe(r.id)}" tabindex="0" role="button"><img src="${safe(art(r))}" alt="${safe(r.name)}"><h3>${safe(r.name)}</h3><span class="badge">${safe(r.rarity||'UNSPECIFIED')}</span><p>${safe(r.civilization?.name||'CIVILIZATION UNAVAILABLE')} · ${date(r.createdAt)}</p></article>`).join('');$('#relicEmpty').style.display=rows.length?'none':'flex';$$('.relic-card').forEach(c=>{const open=()=>selectRelic(state.relics.find(r=>r.id===c.dataset.id));c.onclick=open;c.onkeydown=e=>{if(['Enter',' '].includes(e.key))open()}})}
async function selectRelic(relic){if(!relic)return;state.selectedRelic=relic;try{state.selectedRelic=await api(`/api/relics/${encodeURIComponent(relic.id)}`)}catch{}const r=state.selectedRelic;$('#detailImage').src=art(r);$('#detailName').textContent=r.name||'UNNAMED RELIC';$('#detailRarity').textContent=r.rarity||'UNSPECIFIED';$('#detailDescription').textContent=r.description||'No persisted description is available.';$('#detailCiv').textContent=r.civilization?.name||'—';$('#detailCategory').textContent=r.category||'—';$('#detailMaterial').textContent=r.material||'—';$('#detailEnergy').textContent=r.energySignature||'—';$('#detailDate').textContent=date(r.createdAt);$('#detailOwner').textContent=short(r.user?.walletAddress||state.account);$('#analysisState').textContent=r.name||'RELIC SELECTED';$('#analysisMessage').textContent=r.analyses?.[0]?.status?`Latest persisted analysis: ${r.analyses[0].status}.`:'No persisted analysis exists for this relic.';$('#analyzeBtn').disabled=!state.authenticated;location.hash='relic-detail'}
function renderCivilizations(){const rows=state.civilizations;$('#civilizations').innerHTML=rows.length?rows.map((c,i)=>`<button class="civ-item" data-i="${i}"><b>${safe(c.name)}</b><small>${c.regions?.length??'—'} VERIFIED REGIONS</small></button>`).join(''):'<div class="table-state">NO VERIFIED CIVILIZATIONS</div>';$$('.civ-item').forEach(b=>b.onclick=()=>{const c=rows[+b.dataset.i];$$('.civ-item').forEach(x=>x.classList.toggle('active',x===b));$('#archiveTitle').textContent=c.name;$('#archiveDescription').textContent=c.description||'No persisted civilization description is available.';$('.progress-orb strong').textContent='—'})}
async function hydrate(){renderRegions();try{const[s,regions,civs]=await Promise.all([api('/api/stats'),api('/api/regions'),api('/api/civilizations')]);state.regions=Array.isArray(regions)?regions:[];state.civilizations=Array.isArray(civs)?civs:[];renderRegions();renderCivilizations();[s.explorers,s.relics,s.civilizations,s.archiveRecords].forEach((v,i)=>$$('.stats strong')[i].textContent=Number(v||0).toLocaleString());$('.stats p').textContent='LIVE DATABASE';if(s.featuredRelic){const r=s.featuredRelic;$('#featuredName').textContent=r.name;$('#featuredRarity').textContent=r.rarity||'UNSPECIFIED';$('#featuredDescription').textContent=r.description||'No persisted description is available.';$('#featuredCivilization').textContent=r.civilization?.name||'—';$('#featuredType').textContent=r.category||'—';$('#featuredOwner').textContent=short(r.user?.walletAddress);$('#featuredLink').onclick=e=>{e.preventDefault();selectRelic(r)}}}catch(e){console.info(message(e));renderCivilizations()}}
async function authenticate(){if(!state.account||!window.ethereum)throw Error('WALLET_REQUIRED');const n=await api('/api/auth/nonce',{method:'POST',body:JSON.stringify({walletAddress:state.account})}),chainId=parseInt(await ethereum.request({method:'eth_chainId'}),16),issued=new Date(),expires=new Date(Date.now()+300000),text=`${n.domain} wants you to sign in with your Ethereum account:\n${state.account}\n\nSign in to RELIC ZERO.\n\nURI: ${location.origin}\nVersion: 1\nChain ID: ${chainId}\nNonce: ${n.nonce}\nIssued At: ${issued.toISOString()}\nExpiration Time: ${expires.toISOString()}`,signature=await ethereum.request({method:'personal_sign',params:[text,state.account]});await api('/api/auth/verify',{method:'POST',body:JSON.stringify({message:text,signature})});state.authenticated=true;renderWallet();toast('Explorer identity authenticated.');await Promise.all([loadRelics(),loadProfile()])}
function renderWallet(){$('#walletLabel').textContent=short(state.account);$('#walletBtn').classList.toggle('connected',!!state.account);$('#profileWallet').textContent=state.account||'NOT CONNECTED';$('#profileChain').textContent=state.account?(state.authenticated?'Authenticated explorer session.':'Connected · signature required for private records.'):'Connect your wallet to load private profile data.';$('#expeditionBtn').disabled=!(state.account&&state.selectedRegion)}
async function connect(){if(state.account)return $('#walletMenu').classList.toggle('show');if(!window.ethereum)return toast('No compatible browser wallet was detected.');try{[state.account]=await ethereum.request({method:'eth_requestAccounts'});renderWallet();await authenticate()}catch(e){toast(e.code===4001?'Wallet request cancelled.':message(e))}}
async function loadRelics(){if(!state.authenticated)return;$('#relicEmpty h2').textContent='LOADING VERIFIED RECORDS';try{state.relics=await api('/api/relics?page=1&pageSize=50');$('#relicEmpty h2').textContent='THE GALLERY AWAITS';$('#relicEmpty p').textContent='No verified relics are available for this wallet.';renderRelics()}catch(e){state.relics=[];renderRelics();$('#relicEmpty h2').textContent='COLLECTION UNAVAILABLE';$('#relicEmpty p').textContent=message(e)}}
async function loadLeaderboard(category='discoveries'){$('#leaderRows').className='table-state';if(category!=='discoveries'){ $('#leaderRows').textContent='THIS RANKING IS NOT SUPPORTED BY THE CURRENT API';return }$('#leaderRows').textContent='LOADING VERIFIED RANKINGS';try{const rows=await api('/api/leaderboard?page=1&pageSize=20');if(!rows.length){$('#leaderRows').textContent='NO VERIFIED RANKINGS YET';return}$('#leaderRows').className='';$('#leaderRows').innerHTML=rows.map((r,i)=>`<div class="leader-row"><strong>${String(i+1).padStart(2,'0')}</strong><span>${safe(short(r.walletAddress))}</span><span>${Number(r._count?.relics||0)}</span><span>—</span><span>—</span></div>`).join('')}catch(e){$('#leaderRows').textContent=message(e)}}
async function loadProfile(){if(!state.authenticated)return;try{const[p,relics]=await Promise.all([api('/api/profile'),api('/api/profile/relics')]);$('#profileWallet').textContent=short(p.walletAddress);$('#profileChain').textContent=`Explorer since ${date(p.createdAt)} · ${p._count?.expeditions??0} expeditions`;$('#metricRelics').textContent=p._count?.relics??0;$('#metricLegendary').textContent=relics.filter(r=>r.rarity==='LEGENDARY').length;$('#metricCivs').textContent=new Set(relics.map(r=>r.civilizationId).filter(Boolean)).size;$('.profile-page .state-card h2').textContent=relics.length?'VERIFIED COLLECTION LOADED':'NO VERIFIED RELICS YET';$('.profile-page .state-card p').textContent=relics.length?`${relics.length} persisted relic records belong to this explorer.`:'Complete an expedition to begin your collection.'}catch(e){$('#profileChain').textContent=message(e)}}
async function startExpedition(){if(!state.selectedRegion)return;const b=$('#expeditionBtn');b.disabled=true;b.textContent='VALIDATING…';try{if(!state.authenticated)await authenticate();const x=await api('/api/expeditions',{method:'POST',body:JSON.stringify({regionId:state.selectedRegion.id,idempotencyKey:crypto.randomUUID()})});$('#expeditionStatus').textContent=`Expedition ${x.status.toLowerCase()}. Durable processing has started.`;poll(x.id)}catch(e){$('#expeditionStatus').textContent=message(e);toast(message(e))}finally{b.textContent='START EXPEDITION →';b.disabled=!(state.account&&state.selectedRegion)}}
async function poll(id){try{const x=await api(`/api/expeditions/${encodeURIComponent(id)}`);$('#expeditionStatus').textContent=x.status==='COMPLETED'?`Discovery complete: ${x.relic?.name||'verified relic recorded'}.`:x.status==='FAILED'?`Expedition failed safely: ${x.errorCode||'generation unavailable'}.`:`Expedition ${x.status.toLowerCase()}.`;if(!['COMPLETED','FAILED'].includes(x.status))setTimeout(()=>poll(id),4000);else if(x.status==='COMPLETED')loadRelics()}catch{$('#expeditionStatus').textContent='Status temporarily unavailable. The server record remains safe.'}}
async function analyze(){if(!state.selectedRelic)return toast('Select a verified relic first.');const b=$('#analyzeBtn');b.disabled=true;b.textContent='SUBMITTING…';try{if(!state.authenticated)await authenticate();const x=await api(`/api/relics/${encodeURIComponent(state.selectedRelic.id)}/analyze`,{method:'POST',body:'{}'});$('#analysisState').textContent=x.status||'QUEUED';$('#analysisMessage').textContent='The persisted analysis job has been accepted.';toast('Analysis job accepted.')}catch(e){$('#analysisMessage').textContent=message(e)}finally{b.textContent='ANALYZE RELIC';b.disabled=!state.authenticated}}
addEventListener('hashchange',route);$('.menu-btn').onclick=()=>$('.links').classList.toggle('open');$('#trailerBtn').onclick=()=>toast('Trailer coming soon — no media has been published.');$('.lang-btn').onclick=()=>toast('English is currently the only available language.');$('#walletBtn').onclick=connect;$('#expeditionBtn').onclick=startExpedition;$('#analyzeBtn').onclick=analyze;$('#relicSearch').oninput=e=>{state.search=e.target.value.trim();renderRelics()};$('#relicSort').onchange=e=>{state.sort=e.target.value;renderRelics()};$$('#rarityFilters button').forEach(b=>b.onclick=()=>{state.rarity=b.dataset.rarity;$$('#rarityFilters button').forEach(x=>x.classList.toggle('active',x===b));renderRelics()});$$('#leaderTabs button').forEach(b=>b.onclick=()=>{$$('#leaderTabs button').forEach(x=>x.classList.toggle('active',x===b));loadLeaderboard(b.dataset.category)});$$('.detail-tabs button').forEach(b=>b.onclick=()=>{$$('.detail-tabs button').forEach(x=>x.classList.toggle('active',x===b));if(b.textContent!=='OVERVIEW')toast(`${b.textContent}: no persisted content is available.`)});$$('.profile-tabs button').forEach(b=>b.onclick=()=>{$$('.profile-tabs button').forEach(x=>x.classList.toggle('active',x===b));if(b.textContent!=='MY COLLECTION')toast(`${b.textContent}: not exposed by the current API.`)});
$('#walletMenu').onclick=async e=>{const a=e.target.dataset.action;if(!a)return;if(a==='profile')location.hash='profile';if(a==='copy'&&state.account){await navigator.clipboard.writeText(state.account);toast('Address copied.')}if(a==='switch')toast('Network policy is verified during authentication.');if(a==='disconnect'){try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{}state.account=null;state.authenticated=false;state.relics=[];renderWallet();renderRelics();toast('Explorer session cleared.')}$('#walletMenu').classList.remove('show')};
if(window.ethereum){ethereum.on?.('accountsChanged',a=>{state.account=a[0]||null;state.authenticated=false;renderWallet();toast(state.account?'Account changed. Authenticate again.':'Wallet disconnected.')});ethereum.on?.('chainChanged',()=>{state.authenticated=false;renderWallet();toast('Network changed. Authenticate again.')})}
renderWallet();renderRelics();renderRegions();renderCivilizations();route();hydrate();
